// compact Notion search results
const out = [];
for (const item of $input.all()) {
  if (item.error) { out.push(item); continue; }
  const j = item.json || {};
  if (!Array.isArray(j.results)) { out.push(item); continue; }
  for (const r of j.results.slice(0, 25)) {
    let title = '';
    if (r.object === 'page') {
      const props = r.properties || {};
      for (const k of Object.keys(props)) {
        const p = props[k];
        if (p && p.type === 'title' && Array.isArray(p.title)) { title = p.title.map((t) => t.plain_text).join('').trim(); break; }
      }
    } else if (r.object === 'database') {
      title = Array.isArray(r.title) ? r.title.map((t) => t.plain_text).join('').trim() : '';
    }
    out.push({ json: { type: r.object, title: title || '(بدون عنوان)', id: r.id, url: r.url || null } });
  }
}
return out.length ? out : [{ json: { ok: true, note: 'مفيش نتائج' } }];

// compact a Notion page (title + flattened properties)
const propText = (p) => {
  if (!p || !p.type) return null;
  const t = p.type;
  if (t === 'title') return (p.title || []).map((x) => x.plain_text).join('').trim();
  if (t === 'rich_text') return (p.rich_text || []).map((x) => x.plain_text).join('').trim();
  if (t === 'number') return p.number;
  if (t === 'select') return p.select ? p.select.name : null;
  if (t === 'status') return p.status ? p.status.name : null;
  if (t === 'multi_select') return (p.multi_select || []).map((x) => x.name).join('، ');
  if (t === 'date') return p.date ? (p.date.start + (p.date.end ? ' → ' + p.date.end : '')) : null;
  if (t === 'checkbox') return p.checkbox;
  if (t === 'url') return p.url;
  if (t === 'email') return p.email;
  if (t === 'phone_number') return p.phone_number;
  if (t === 'people') return (p.people || []).map((x) => x.name).join('، ');
  if (t === 'relation') return ((p.relation || []).length) + ' مرتبط';
  if (t === 'formula') { const f = p.formula || {}; return f.string !== undefined ? f.string : (f.number !== undefined ? f.number : (f.boolean !== undefined ? f.boolean : null)); }
  return null;
};
const out = [];
for (const item of $input.all()) {
  if (item.error) { out.push(item); continue; }
  const j = item.json || {};
  if (j.object !== 'page' || !j.id) { out.push(item); continue; }
  const props = {};
  let title = '';
  for (const k of Object.keys(j.properties || {})) {
    const v = propText(j.properties[k]);
    if (v === null || v === undefined || v === '') continue;
    props[k] = v;
    if (j.properties[k].type === 'title') title = String(v);
  }
  out.push({ json: { id: j.id, title: title || '(بدون عنوان)', url: j.url || null, created: String(j.created_time || '').slice(0, 16), edited: String(j.last_edited_time || '').slice(0, 16), properties: props } });
}
return out;

