// read a Notion page's blocks as plain lines
const rich = (rt) => (rt || []).map((x) => x.plain_text).join('');
const out = [];
for (const item of $input.all()) {
  if (item.error) { out.push(item); continue; }
  const j = item.json || {};
  if (j.object !== 'list' || !Array.isArray(j.results)) { out.push(item); continue; }
  const lines = [];
  for (const b of j.results) {
    const t = b.type;
    const d = (b[t] || {});
    let s = '';
    if (t === 'child_page') s = '📄 ' + String(d.title || '');
    else if (t === 'to_do') s = (d.checked ? '☑ ' : '☐ ') + rich(d.rich_text);
    else s = rich(d.rich_text);
    if (!s || !String(s).trim()) continue;
    if (t === 'heading_1') s = '# ' + s;
    else if (t === 'heading_2') s = '## ' + s;
    else if (t === 'heading_3') s = '### ' + s;
    else if (t === 'bulleted_list_item') s = '• ' + s;
    else if (t === 'numbered_list_item') s = '‣ ' + s;
    else if (t === 'quote') s = '« ' + s;
    lines.push(s);
  }
  out.push({ json: { ok: true, count: j.results.length, has_more: !!j.has_more, lines } });
}
return out;

